INSERT INTO questions (company_id,category,difficulty,question_text,expected_keywords,input_format,output_format) SELECT 1,'DSA','easy','Two Sum: Given an array of integers and a target, return the indices of two distinct elements whose sum equals the target.',ARRAY['hashmap','two sum','O(n)','indices'],'The first line contains n and target. The second line contains n integers.','Print the two zero-based indices. If no pair exists, print -1 -1.' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE company_id=1 AND question_text='Two Sum: Given an array of integers and a target, return the indices of two distinct elements whose sum equals the target.');
